-- 396: Original BrillaPrep NSMQ subj_nsmq_chemistry round_one beta questions (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_396_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_396_guard;
INSERT INTO _migration_396_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b001_001' AND NOT (q.topic_id IS 'topic_atomic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which subatomic particle carries a negative charge?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Electron","B. Proton","C. Neutron","D. Atomic nucleus"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Electrons carry a charge of −1.6 × 10⁻¹⁹ C and occupy the region around the nucleus. Protons are positively charged, neutrons are neutral, and the nucleus as a whole is positive.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b001_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_396_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b001_002' AND NOT (q.topic_id IS 'topic_bonding' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which type of bond forms when electrons are completely transferred from a metal atom to a non-metal atom?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Covalent bond","B. Ionic bond","C. Metallic bond","D. Hydrogen bond"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Complete transfer of electrons produces oppositely charged ions that attract electrostatically — an ionic bond, as in NaCl. Covalent bonding involves sharing, and metallic bonding involves a sea of delocalised electrons.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b001_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_396_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b001_003' AND NOT (q.topic_id IS 'topic_organic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the IUPAC name of CH₃CH(OH)CH₃?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Propan-1-ol","B. Ethanol","C. Propan-2-ol","D. Propanone"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The longest chain has three carbons (propan-) and the −OH group sits on carbon 2, so the name is propan-2-ol. Propan-1-ol is the straight-chain isomer CH₃CH₂CH₂OH, and propanone is the ketone CH₃COCH₃.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b001_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_396_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_r1_b001_004' AND NOT (q.topic_id IS 'topic_stoichiometry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How many moles are present in 54 g of water? (H₂O = 18 g/mol)' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 1","B. 2","C. 6","D. 3"]' AND q.correct_answer IS 'D' AND q.explanation IS 'n = m/M = 54/18 = 3 mol. This uses the defining mole relation; each mole of water contains 6.02 × 10²³ molecules, so 54 g holds about 1.8 × 10²⁴ molecules.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_r1_b001_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
