INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_r1_b001_004', 'topic_stoichiometry', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'How many moles are present in 54 g of water? (H₂O = 18 g/mol)', 'multiple_choice', 'round_one', '["A. 1","B. 2","C. 6","D. 3"]', 'D', 'n = m/M = 54/18 = 3 mol. This uses the defining mole relation; each mole of water contains 6.02 × 10²³ molecules, so 54 g holds about 1.8 × 10²⁴ molecules.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
